import type { AlertDialogState, StateAttrMap } from '@webplayer/core';
import { createContext } from '@webplayer/element/context';

export interface AlertDialogContextValue {
  state: AlertDialogState;
  stateAttrMap: StateAttrMap<AlertDialogState>;
  close: () => void;
}

const ALERT_DIALOG_CONTEXT_KEY = Symbol('@webplayer/alert-dialog');

export const alertDialogContext = createContext<AlertDialogContextValue>(ALERT_DIALOG_CONTEXT_KEY);
